Aggregation Pipeline // Revenue analysis by product category
db.orders.aggregate([
  { $match: { status: "completed", createdAt: { $gte: ISODate("2024-01-01") } } },
  { $unwind: "$items" },
  {
    $lookup: {
      from: "products",
      localField: "items.productId",
      foreignField: "sku",
      as: "productDetails"
    }
  },
  { $unwind: "$productDetails" },
  {
    $group: {
      _id: "$productDetails.category",
      totalRevenue: { $sum: { $multiply: ["$items.price", "$items.quantity"] } },
      orderCount: { $sum: 1 },
      avgOrderValue: { $avg: { $multiply: ["$items.price", "$items.quantity"] } }
    }
  },
  { $sort: { totalRevenue: -1 } },
  {
    $project: {
      category: "$_id",
      totalRevenue: { $round: ["$totalRevenue", 2] },
      orderCount: 1,
      avgOrderValue: { $round: ["$avgOrderValue", 2] },
      _id: 0
    }
  }
]);

Indexing Strategies // Compound index for common query patterns
db.orders.createIndex(
  { customerId: 1, status: 1, createdAt: -1 },
  { name: "customer_status_date_idx" }
);

// Partial index for active orders only
db.orders.createIndex(
  { createdAt: -1 },
  {
    partialFilterExpression: { status: { $in: ["pending", "processing"] } },
    name: "active_orders_idx"
  }
);

// TTL index for automatic document expiration
db.sessions.createIndex(
  { lastAccessedAt: 1 },
  { expireAfterSeconds: 3600, name: "session_ttl_idx" }
);

// Text index for full-text search
db.products.createIndex(
  { name: "text", description: "text", tags: "text" },
  { weights: { name: 10, tags: 5, description: 1 } }
);

Exchanges Exchanges are the routing layer in RabbitMQ. Producers never send messages directly to queues; instead, they publish to an exchange, which then routes copies of the message to zero or more queues based on the exchange type and binding rules. Understanding exchange types is fundamental to designing effective messaging topologies. A direct exchange routes messages to queues whose binding key exactly matches the message routing key. This is the simplest routing model and works well for point-to-point communication where each message type has a dedicated consumer. The default exchange (empty string name) is a special direct exchange that automatically binds to every queue using the queue name as the routing key. A fanout exchange ignores routing keys entirely and broadcasts every message to all bound queues. This is the publish-subscribe pattern: one producer, many consumers each receiving every message. Use fanout exchanges for event notification systems where multiple services need to react to the same event independently. A topic exchange routes messages based on wildcard pattern matching against the routing key. Routing keys are dot-delimited strings (e.g., order.created.us), and binding patterns use * (match exactly one word) and # (match zero or more words). Topic exchanges provide flexible content-based routing without requiring a binding for every possible routing key value. A headers exchange ignores the routing key and routes based on message header attributes. The binding specifies header key-value pairs and a match type (x-match: all requires all headers to match, x-match: any requires at least one). Headers exchanges are useful when routing decisions depend on multiple attributes that do not fit cleanly into a single routing key string. // Declaring exchanges with Spring AMQP
@Configuration
public class RabbitExchangeConfig {

    @Bean
    public DirectExchange orderExchange() {
        return ExchangeBuilder.directExchange("order.direct")
            .durable(true)
            .build();
    }

    @Bean
    public FanoutExchange notificationExchange() {
        return ExchangeBuilder.fanoutExchange("notification.fanout")
            .durable(true)
            .build();
    }

    @Bean
    public TopicExchange eventExchange() {
        return ExchangeBuilder.topicExchange("event.topic")
            .durable(true)
            .build();
    }

    @Bean
    public HeadersExchange auditExchange() {
        return ExchangeBuilder.headersExchange("audit.headers")
            .durable(true)
            .build();
    }
}

Queues Queues are the storage mechanism in RabbitMQ where messages wait until a consumer retrieves them. Each queue is an ordered FIFO buffer residing on a single node (unless using quorum queues or classic mirrored queues). Queue properties determine durability, exclusivity, auto-deletion behavior, and advanced features like TTL and length limits. Classic queues are the traditional queue type. They reside on a single node with optional mirroring to other nodes for high availability. Classic queues support all features including priority, lazy mode, and per-message TTL. However, mirrored classic queues have known issues with synchronization and are being deprecated in favor of quorum queues. Quorum queues (RabbitMQ 3.8+) use the Raft consensus algorithm to replicate messages across multiple nodes. They provide stronger data safety guarantees than mirrored classic queues, with automatic leader election and consistent replication. Quorum queues are the recommended choice for durable, replicated queues in production. They do not support some classic queue features like priority and non-durable modes, but offer poison message handling via delivery count tracking. Lazy queues move messages to disk as early as possible, keeping only a small buffer in memory. This is useful for queues that accumulate millions of messages (e.g., during consumer downtime) where keeping everything in memory would exhaust available RAM. In RabbitMQ 3.12+, all classic queues use a lazy-like storage engine by default. // Queue declarations with various configurations
@Configuration
public class RabbitQueueConfig {

    @Bean
    public Queue orderQueue() {
        return QueueBuilder.durable("order.processing")
            .withArgument("x-queue-type", "quorum")  // Quorum queue
            .withArgument("x-delivery-limit", 5)      // Max redeliveries
            .build();
    }

    @Bean
    public Queue notificationQueue() {
        return QueueBuilder.durable("notification.email")
            .withArgument("x-message-ttl", 86400000)  // 24h TTL
            .withArgument("x-max-length", 100000)     // Max 100k messages
            .withArgument("x-overflow", "reject-publish") // Reject when full
            .build();
    }

    @Bean
    public Queue temporaryQueue() {
        return QueueBuilder.nonDurable()
            .autoDelete()
            .exclusive()
            .build();
    }
}

Bindings Bindings are the rules that connect exchanges to queues (or other exchanges). A binding defines the relationship between an exchange and a queue, specifying under what conditions messages arriving at the exchange should be copied to the queue. Without bindings, messages published to an exchange are discarded because there is no route to any queue. For direct exchanges, the binding key is a simple string that must exactly match the routing key of the published message. You can bind multiple queues with the same binding key to achieve fanout-like behavior on a direct exchange, or bind one queue with multiple binding keys to receive messages from different routing keys. For topic exchanges, the binding key is a dot-delimited pattern. The wildcard * substitutes for exactly one word, and # substitutes for zero or more words. For example, binding key order.*.us matches routing keys order.created.us and order.cancelled.us but not order.created.eu or order.item.created.us. Exchange-to-exchange bindings allow you to create routing topologies where one exchange forwards messages to another exchange before they reach queues. This enables layered routing architectures where a top-level topic exchange routes to specialized direct exchanges, each serving a different consumer group. // Binding configuration with Spring AMQP
@Configuration
public class RabbitBindingConfig {

    @Bean
    public Binding orderBinding(Queue orderQueue, DirectExchange orderExchange) {
        return BindingBuilder.bind(orderQueue)
            .to(orderExchange)
            .with("order.process");  // Routing key
    }

    @Bean
    public Binding notificationBinding(Queue notificationQueue, FanoutExchange notificationExchange) {
        return BindingBuilder.bind(notificationQueue)
            .to(notificationExchange);  // No routing key for fanout
    }

    @Bean
    public Binding eventBinding(Queue orderQueue, TopicExchange eventExchange) {
        return BindingBuilder.bind(orderQueue)
            .to(eventExchange)
            .with("order.#");  // Matches order.created, order.cancelled, etc.
    }

    @Bean
    public Binding auditBinding(Queue auditQueue, HeadersExchange auditExchange) {
        return BindingBuilder.bind(auditQueue)
            .to(auditExchange)
            .whereAll("source", "action").match();  // Match all specified headers
    }
}

Acknowledgments Acknowledgments are the mechanism by which consumers confirm successful message processing to the broker. Proper acknowledgment handling is critical for reliable messaging because it determines whether a message is removed from the queue or redelivered to another consumer. RabbitMQ supports both consumer acknowledgments (from consumer to broker) and publisher confirms (from broker to publisher). Consumer acknowledgments come in three modes. In auto-ack mode (autoAck=true), the broker considers a message delivered the moment it sends it to the consumer, regardless of whether processing succeeds. This provides at-most-once delivery with the highest throughput but risks message loss on consumer failure. In manual-ack mode, the consumer explicitly sends basic.ack after successful processing, basic.nack to reject and optionally requeue, or basic.reject for a single message rejection. Manual acknowledgment provides at-least-once delivery guarantees. Publisher confirms are the producer-side equivalent. When a channel is put into confirm mode, the broker acknowledges each published message with a basic.ack once it has been persisted (for persistent messages) or routed to at least one queue. If the message cannot be routed, the broker sends basic.nack. Publisher confirms combined with consumer manual acks provide end-to-end delivery guarantees. Prefetch count (basic.qos) controls how many unacknowledged messages the broker delivers to a consumer at once. Setting prefetch to 1 ensures fair dispatch across consumers but reduces throughput. Higher prefetch values improve throughput by allowing consumers to pipeline processing but risk uneven load distribution if processing times vary significantly. // Consumer with manual acknowledgment using Spring AMQP
@Component
public class OrderConsumer {

    @RabbitListener(queues = "order.processing", ackMode = "MANUAL")
    public void processOrder(Message message, Channel channel,
                             @Header(AmqpHeaders.DELIVERY_TAG) long deliveryTag) {
        try {
            OrderEvent order = deserialize(message);
            orderService.process(order);

            // Acknowledge successful processing
            channel.basicAck(deliveryTag, false);  // false = single message
            log.info("Processed order: {}", order.getOrderId());

        } catch (RecoverableException e) {
            // Requeue for retry
            channel.basicNack(deliveryTag, false, true);  // requeue=true
            log.warn("Requeueing order due to transient error", e);

        } catch (PoisonMessageException e) {
            // Reject without requeue (send to DLQ if configured)
            channel.basicReject(deliveryTag, false);  // requeue=false
            log.error("Rejecting poison message", e);
        }
    }
}

// Publisher confirms configuration
@Configuration
public class PublisherConfirmConfig {

    @Bean
    public CachingConnectionFactory connectionFactory() {
        CachingConnectionFactory factory = new CachingConnectionFactory("localhost");
        factory.setPublisherConfirmType(ConfirmType.CORRELATED);
        factory.setPublisherReturns(true);
        return factory;
    }

    @Bean
    public RabbitTemplate rabbitTemplate(CachingConnectionFactory connectionFactory) {
        RabbitTemplate template = new RabbitTemplate(connectionFactory);
        template.setMandatory(true);

        template.setConfirmCallback((correlationData, ack, cause) -> {
            if (!ack) {
                log.error("Message not confirmed: {}", cause);
                // Retry or alert
            }
        });

        template.setReturnsCallback(returned -> {
            log.warn("Message returned: exchange={}, routingKey={}, replyCode={}",
                returned.getExchange(), returned.getRoutingKey(), returned.getReplyCode());
        });

        return template;
    }
}

Dead-Letter Queues Dead-letter queues (DLQs) are queues that receive messages which could not be processed successfully. RabbitMQ implements dead-lettering through dead-letter exchanges (DLXs): when a message is rejected, expires, or exceeds a queue length limit, it is republished to the configured dead-letter exchange, which routes it to a dead-letter queue. DLQs are essential for building resilient systems that handle failures gracefully without losing messages. Messages are dead-lettered in three scenarios: the consumer rejects the message with requeue=false (via basic.reject or basic.nack), the message TTL expires while sitting in the queue, or the queue exceeds its maximum length and the overflow strategy is set to reject-publish-dlx or the default drop-head behavior pushes messages out. When a message is dead-lettered, RabbitMQ adds headers to the message recording the reason for dead-lettering (x-death header array), the original exchange and routing key, the queue from which it was dead-lettered, and a count of how many times it has been dead-lettered. This metadata is invaluable for debugging and implementing retry logic. A common pattern is the retry with backoff topology: the main queue dead-letters to a retry exchange, which routes to a delay queue with a TTL. When the TTL expires, the delay queue dead-letters back to the original exchange, creating a retry loop with configurable delay. After a maximum number of retries (tracked via the x-death count header), the message is routed to a parking lot queue for manual inspection. // Dead-letter queue configuration
@Configuration
public class DeadLetterConfig {

    // Main queue with DLX configuration
    @Bean
    public Queue orderQueue() {
        return QueueBuilder.durable("order.processing")
            .withArgument("x-dead-letter-exchange", "order.dlx")
            .withArgument("x-dead-letter-routing-key", "order.dead")
            .build();
    }

    // Dead-letter exchange
    @Bean
    public DirectExchange deadLetterExchange() {
        return new DirectExchange("order.dlx");
    }

    // Dead-letter queue
    @Bean
    public Queue deadLetterQueue() {
        return QueueBuilder.durable("order.dlq").build();
    }

    @Bean
    public Binding deadLetterBinding() {
        return BindingBuilder.bind(deadLetterQueue())
            .to(deadLetterExchange())
            .with("order.dead");
    }

    // Retry queue with TTL (messages wait here before retry)
    @Bean
    public Queue retryQueue() {
        return QueueBuilder.durable("order.retry")
            .withArgument("x-message-ttl", 30000)  // 30 second delay
            .withArgument("x-dead-letter-exchange", "order.direct")
            .withArgument("x-dead-letter-routing-key", "order.process")
            .build();
    }
}

// Consumer with retry count checking
@Component
public class OrderConsumerWithRetry {

    private static final int MAX_RETRIES = 3;

    @RabbitListener(queues = "order.processing", ackMode = "MANUAL")
    public void processOrder(Message message, Channel channel,
                             @Header(AmqpHeaders.DELIVERY_TAG) long deliveryTag) {
        int retryCount = getRetryCount(message);

        try {
            orderService.process(deserialize(message));
            channel.basicAck(deliveryTag, false);
        } catch (Exception e) {
            if (retryCount >= MAX_RETRIES) {
                // Send to DLQ (parking lot) for manual inspection
                channel.basicReject(deliveryTag, false);
                log.error("Max retries exceeded, sending to DLQ", e);
            } else {
                // Requeue to retry queue via DLX
                channel.basicNack(deliveryTag, false, false);
                log.warn("Retry {} of {}", retryCount + 1, MAX_RETRIES, e);
            }
        }
    }

    private int getRetryCount(Message message) {
        List<Map<String, ?>> deaths = message.getMessageProperties().getXDeathHeader();
        if (deaths == null || deaths.isEmpty()) return 0;
        return deaths.stream()
            .mapToInt(d -> ((Number) d.get("count")).intValue())
            .sum();
    }
}

Rate Limiters Rate limiters control the number of calls permitted within a time period, protecting services from being overwhelmed by bursts of traffic. Resilience4j implements a token bucket algorithm where tokens are replenished at a fixed rate. Each call consumes one token, and when no tokens are available, the caller either waits for the configured timeout duration or receives a RequestNotPermitted exception immediately. Rate limiting is essential for protecting shared resources, enforcing API quotas, and preventing a single client from monopolizing service capacity. Unlike circuit breakers which react to failures, rate limiters proactively prevent overload before failures occur. You can apply rate limiters at the service boundary to protect downstream dependencies, or at the API gateway level to enforce per-client quotas. The limitForPeriod setting defines how many calls are permitted in each limitRefreshPeriod. The timeoutDuration controls how long a thread will wait for permission before throwing an exception. Setting timeout to zero makes the rate limiter non-blocking, immediately rejecting excess calls. // Rate limiter configuration
RateLimiterConfig config = RateLimiterConfig.custom()
    .limitForPeriod(100)                    // 100 calls per period
    .limitRefreshPeriod(Duration.ofSeconds(1)) // Period = 1 second (100 RPS)
    .timeoutDuration(Duration.ofMillis(500))   // Wait up to 500ms for permission
    .build();

RateLimiterRegistry registry = RateLimiterRegistry.of(config);
RateLimiter rateLimiter = registry.rateLimiter("externalApi");

// Decorate a function
Function<SearchRequest, SearchResponse> decoratedSearch = RateLimiter
    .decorateFunction(rateLimiter, request -> searchClient.search(request));

// Use with Spring annotation
@RateLimiter(name = "externalApi", fallbackMethod = "searchFallback")
public SearchResponse search(SearchRequest request) {
    return searchClient.search(request);
}

public SearchResponse searchFallback(SearchRequest request, RequestNotPermitted ex) {
    return SearchResponse.cached(cacheService.getLastResult(request));
}

Retry The retry module automatically retries failed operations with configurable backoff strategies, handling transient failures that resolve themselves after a short delay. Resilience4j retry supports fixed wait intervals, exponential backoff, and randomized intervals to avoid thundering herd problems when multiple instances retry simultaneously. You configure which exceptions trigger a retry and which should propagate immediately. For example, a SocketTimeoutException is worth retrying because the network may recover, but a ValidationException indicates a permanent problem that retrying will not fix. You can also configure retry based on the result of the call, retrying when the response indicates a transient error (like HTTP 503) even though no exception was thrown. Exponential backoff with jitter is the recommended strategy for production systems. It spaces out retries exponentially (1s, 2s, 4s, 8s) and adds random jitter to prevent synchronized retry storms across multiple service instances. The IntervalBiFunction interface allows custom backoff logic based on the attempt number and the last exception or result. // Retry with exponential backoff and jitter
RetryConfig config = RetryConfig.custom()
    .maxAttempts(4)                              // Initial call + 3 retries
    .waitDuration(Duration.ofMillis(500))        // Base wait duration
    .intervalFunction(IntervalFunction.ofExponentialRandomBackoff(
        Duration.ofMillis(500),                  // Initial interval
        2.0,                                     // Multiplier
        Duration.ofSeconds(10)                   // Max interval cap
    ))
    .retryOnResult(response -> response.getStatusCode() == 503)
    .retryExceptions(IOException.class, TimeoutException.class)
    .ignoreExceptions(ValidationException.class, AuthenticationException.class)
    .failAfterMaxAttempts(true)                  // Throw MaxRetriesExceededException
    .build();

RetryRegistry registry = RetryRegistry.of(config);
Retry retry = registry.retry("inventoryService");

// Decorate and execute
Supplier<InventoryResponse> retryableSupplier = Retry
    .decorateSupplier(retry, () -> inventoryClient.checkStock(productId));

// Combine with circuit breaker (retry wraps circuit breaker)
Supplier<InventoryResponse> resilientSupplier = Decorators.ofSupplier(
        () -> inventoryClient.checkStock(productId))
    .withRetry(retry)
    .withCircuitBreaker(circuitBreaker)
    .decorate();

Bulkhead Bulkheads isolate different parts of your application so that a failure or resource exhaustion in one area does not cascade to others. The name comes from ship construction where watertight compartments prevent a hull breach from sinking the entire vessel. Resilience4j provides two bulkhead implementations: semaphore-based and thread pool-based. The semaphore bulkhead limits the number of concurrent calls to a protected function. When the maximum concurrent calls are reached, additional callers either wait for the configured timeout or receive a BulkheadFullException. This is lightweight and does not require separate thread pools, making it suitable for most use cases. The thread pool bulkhead executes calls in a dedicated thread pool, providing stronger isolation because the calling thread is not blocked. It returns a CompletableFuture and is ideal when you need to protect your main thread pool from being exhausted by slow downstream calls. The thread pool bulkhead also provides a queue for excess requests, allowing brief bursts above the core pool size. Use bulkheads when your service has multiple downstream dependencies with different reliability characteristics. For example, if your order service calls both a payment service and a notification service, a bulkhead ensures that a slow notification service cannot consume all threads and prevent payment processing. // Semaphore bulkhead configuration
BulkheadConfig semaphoreConfig = BulkheadConfig.custom()
    .maxConcurrentCalls(25)                     // Max 25 concurrent calls
    .maxWaitDuration(Duration.ofMillis(200))    // Wait up to 200ms for permission
    .build();

Bulkhead bulkhead = Bulkhead.of("paymentService", semaphoreConfig);

// Thread pool bulkhead configuration
ThreadPoolBulkheadConfig threadPoolConfig = ThreadPoolBulkheadConfig.custom()
    .maxThreadPoolSize(10)                      // Max 10 threads
    .coreThreadPoolSize(5)                      // Core 5 threads
    .queueCapacity(20)                          // Queue up to 20 requests
    .keepAliveDuration(Duration.ofSeconds(30))  // Idle thread timeout
    .build();

ThreadPoolBulkhead threadPoolBulkhead = ThreadPoolBulkhead.of("notificationService", threadPoolConfig);

// Execute with thread pool bulkhead (returns CompletableFuture)
CompletableFuture<NotificationResult> future = threadPoolBulkhead.executeSupplier(
    () -> notificationClient.sendEmail(notification)
);

// Spring Boot annotation
@Bulkhead(name = "paymentService", fallbackMethod = "paymentFallback", type = Bulkhead.Type.SEMAPHORE)
public PaymentResponse processPayment(PaymentRequest request) {
    return paymentClient.charge(request);
}

Time Limiter The time limiter enforces a maximum execution duration for asynchronous operations, preventing slow calls from blocking threads indefinitely. It wraps a CompletableFuture or CompletionStage and cancels the operation if it does not complete within the configured timeout. When the timeout expires, the caller receives a TimeoutException and the underlying future is cancelled. Time limiters are critical for maintaining responsiveness in systems where downstream services may become unresponsive without explicitly failing. Without a time limiter, a thread waiting on a hung connection can be blocked for minutes (depending on TCP timeout settings), consuming resources and degrading the overall system. The time limiter provides a predictable upper bound on call duration regardless of network-level timeout configurations. In Spring Boot applications, the time limiter integrates with @Async methods and reactive types. It is commonly combined with a circuit breaker so that timeouts count as failures toward the circuit breaker threshold. The cancelRunningFuture option controls whether the underlying operation is interrupted when the timeout fires, which is important for operations that hold database connections or other resources. // Time limiter configuration
TimeLimiterConfig config = TimeLimiterConfig.custom()
    .timeoutDuration(Duration.ofSeconds(3))     // Max 3 seconds
    .cancelRunningFuture(true)                  // Cancel the future on timeout
    .build();

TimeLimiterRegistry registry = TimeLimiterRegistry.of(config);
TimeLimiter timeLimiter = registry.timeLimiter("reportService");

// Decorate a CompletableFuture supplier
Supplier<CompletableFuture<Report>> futureSupplier =
    () -> CompletableFuture.supplyAsync(() -> reportService.generateReport(params));

Callable<Report> decoratedCall = TimeLimiter.decorateCompletionStage(
    timeLimiter, scheduledExecutor, futureSupplier).toCompletableFuture()::get;

// Combined with circuit breaker in Spring Boot
@TimeLimiter(name = "reportService")
@CircuitBreaker(name = "reportService", fallbackMethod = "reportFallback")
public CompletableFuture<Report> generateReport(ReportParams params) {
    return CompletableFuture.supplyAsync(() -> reportService.generate(params));
}

public CompletableFuture<Report> reportFallback(ReportParams params, TimeoutException ex) {
    return CompletableFuture.completedFuture(Report.cachedOrEmpty(params));
}

Spring Security Configuration with JWT Authentication @Configuration
@EnableWebSecurity
@EnableMethodSecurity
public class SecurityConfig {

    private final JwtAuthenticationFilter jwtFilter;
    private final AuthenticationProvider authProvider;

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        return http
            .csrf(csrf -> csrf.disable()) // Disabled for stateless JWT APIs
            .sessionManagement(session ->
                session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/auth/**").permitAll()
                .requestMatchers("/actuator/health").permitAll()
                .requestMatchers("/api/admin/**").hasRole("ADMIN")
                .requestMatchers("/api/**").authenticated()
                .anyRequest().denyAll())
            .authenticationProvider(authProvider)
            .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class)
            .build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(12);
    }

    @Bean
    public CorsConfigurationSource corsConfigurationSource() {
        CorsConfiguration config = new CorsConfiguration();
        config.setAllowedOrigins(List.of("https://app.example.com"));
        config.setAllowedMethods(List.of("GET", "POST", "PUT", "DELETE"));
        config.setAllowedHeaders(List.of("Authorization", "Content-Type"));
        config.setMaxAge(3600L);
        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration("/api/**", config);
        return source;
    }
}

