BFS Using a Queue Breadth-first search is the canonical queue application, exploring nodes level by level in a graph or tree. public List<Integer> bfs(Map<Integer, List<Integer>> graph, int start) {
    List<Integer> visited = new ArrayList<>();
    Queue<Integer> queue = new ArrayDeque<>();
    Set<Integer> seen = new HashSet<>();

    queue.offer(start);
    seen.add(start);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        visited.add(current);
        for (int neighbor : graph.getOrDefault(current, Collections.emptyList())) {
            if (!seen.contains(neighbor)) {
                seen.add(neighbor);
                queue.offer(neighbor);
            }
        }
    }
    return visited;
}

Sliding Window Maximum Using Deque A monotonic deque maintains elements in decreasing order, enabling O(n) sliding window maximum computation. public int[] maxSlidingWindow(int[] nums, int k) {
    Deque<Integer> deque = new ArrayDeque<>();  // Stores indices
    int[] result = new int[nums.length - k + 1];

    for (int i = 0; i < nums.length; i++) {
        // Remove elements outside the window
        while (!deque.isEmpty() && deque.peekFirst() <= i - k) {
            deque.pollFirst();
        }
        // Remove smaller elements from the back
        while (!deque.isEmpty() && nums[deque.peekLast()] <= nums[i]) {
            deque.pollLast();
        }
        deque.offerLast(i);
        if (i >= k - 1) {
            result[i - k + 1] = nums[deque.peekFirst()];
        }
    }
    return result;
}

Producer-Consumer with BlockingQueue BlockingQueue provides thread-safe FIFO operations with blocking semantics, ideal for concurrent producer-consumer patterns. public class ProducerConsumer {
    private final BlockingQueue<String> queue = new ArrayBlockingQueue<>(100);

    public void produce(String item) throws InterruptedException {
        queue.put(item);  // Blocks if queue is full
    }

    public String consume() throws InterruptedException {
        return queue.take();  // Blocks if queue is empty
    }
}

Example Implementation: class RingBuffer {
    private int[] buffer;
    private int head = 0;
    private int tail = 0;
    private int size = 0;
    private int capacity;

    public RingBuffer(int capacity) {
        this.capacity = capacity;
        this.buffer = new int[capacity];
    }

    public void enqueue(int value) {
        if (size == capacity) {
            System.out.println("Buffer is full. Overwriting oldest element.");
            head = (head + 1) % capacity;
            size--;
        }
        buffer[tail] = value;
        tail = (tail + 1) % capacity;
        size++;
    }

    public int dequeue() {
        if (size == 0) {
            throw new RuntimeException("Buffer is empty!");
        }
        int value = buffer[head];
        head = (head + 1) % capacity;
        size--;
        return value;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public boolean isFull() {
        return size == capacity;
    }

    public void printBuffer() {
        System.out.print("Buffer: ");
        for (int i = 0; i < size; i++) {
            System.out.print(buffer[(head + i) % capacity] + " ");
        }
        System.out.println();
    }
}

Example Usage: public class Main {
    public static void main(String[] args) {
        RingBuffer rb = new RingBuffer(3);

        rb.enqueue(10);
        rb.enqueue(20);
        rb.enqueue(30);
        rb.printBuffer();  // Output: Buffer: 10 20 30

        rb.enqueue(40);  // Overwrites oldest element (10)
        rb.printBuffer();  // Output: Buffer: 20 30 40

        System.out.println("Dequeued: " + rb.dequeue());  // Output: Dequeued: 20
        rb.printBuffer();  // Output: Buffer: 30 40
    }
}

Generic Ring Buffer with Overwrite Policy A production-quality ring buffer that supports configurable behavior when full: either overwrite the oldest element or reject the new one. public class RingBuffer<T> {
    private final Object[] buffer;
    private int head = 0;
    private int tail = 0;
    private int size = 0;
    private final int capacity;
    private final boolean overwriteOnFull;

    public RingBuffer(int capacity, boolean overwriteOnFull) {
        this.capacity = capacity;
        this.buffer = new Object[capacity];
        this.overwriteOnFull = overwriteOnFull;
    }

    public boolean offer(T element) {
        if (size == capacity) {
            if (!overwriteOnFull) return false;
            head = (head + 1) % capacity;  // Drop oldest
            size--;
        }
        buffer[tail] = element;
        tail = (tail + 1) % capacity;
        size++;
        return true;
    }

    @SuppressWarnings("unchecked")
    public T poll() {
        if (size == 0) return null;
        T element = (T) buffer[head];
        buffer[head] = null;  // Help GC
        head = (head + 1) % capacity;
        size--;
        return element;
    }

    public int size() { return size; }
    public boolean isEmpty() { return size == 0; }
    public boolean isFull() { return size == capacity; }
}

Lock-Free SPSC Ring Buffer A single-producer single-consumer ring buffer using volatile variables for thread-safe communication without locks. This pattern is used in high-performance messaging systems. public class SPSCRingBuffer<T> {
    private final Object[] buffer;
    private final int capacity;
    private volatile long head = 0;  // Consumer reads from here
    private volatile long tail = 0;  // Producer writes here

    public SPSCRingBuffer(int capacity) {
        this.capacity = capacity;
        this.buffer = new Object[capacity];
    }

    // Called by producer thread only
    public boolean offer(T element) {
        long currentTail = tail;
        if (currentTail - head >= capacity) return false;  // Full
        buffer[(int)(currentTail % capacity)] = element;
        tail = currentTail + 1;  // Volatile write publishes the element
        return true;
    }

    // Called by consumer thread only
    @SuppressWarnings("unchecked")
    public T poll() {
        long currentHead = head;
        if (currentHead >= tail) return null;  // Empty
        T element = (T) buffer[(int)(currentHead % capacity)];
        head = currentHead + 1;  // Volatile write releases the slot
        return element;
    }
}

