Jenkins Declarative Pipeline // Jenkinsfile - Declarative pipeline
pipeline {
    agent {
        kubernetes {
            yaml '''
                apiVersion: v1
                kind: Pod
                spec:
                  containers:
                  - name: gradle
                    image: gradle:8.4-jdk17
                    command: ['sleep', '99d']
                  - name: docker
                    image: docker:24
                    command: ['sleep', '99d']
                    volumeMounts:
                    - name: docker-sock
                      mountPath: /var/run/docker.sock
                  volumes:
                  - name: docker-sock
                    hostPath:
                      path: /var/run/docker.sock
            '''
        }
    }

    environment {
        DOCKER_REGISTRY = 'registry.example.com'
        IMAGE_NAME = "${DOCKER_REGISTRY}/app:${env.BUILD_NUMBER}"
        GRADLE_OPTS = '-Dorg.gradle.daemon=false'
    }

    options {
        timeout(time: 30, unit: 'MINUTES')
        disableConcurrentBuilds()
        buildDiscarder(logRotator(numToKeepStr: '10'))
    }

    stages {
        stage('Build') {
            steps {
                container('gradle') {
                    sh 'gradle assemble --no-daemon'
                }
            }
        }

        stage('Test') {
            parallel {
                stage('Unit Tests') {
                    steps {
                        container('gradle') {
                            sh 'gradle test --no-daemon'
                        }
                    }
                    post {
                        always {
                            junit 'build/test-results/test/*.xml'
                        }
                    }
                }
                stage('Integration Tests') {
                    steps {
                        container('gradle') {
                            sh 'gradle integrationTest --no-daemon'
                        }
                    }
                }
            }
        }

        stage('Package') {
            steps {
                container('docker') {
                    sh "docker build -t ${IMAGE_NAME} ."
                    sh "docker push ${IMAGE_NAME}"
                }
            }
        }

        stage('Deploy Staging') {
            when {
                branch 'main'
            }
            steps {
                sh "kubectl set image deployment/app app=${IMAGE_NAME} -n staging"
                sh "kubectl rollout status deployment/app -n staging --timeout=300s"
            }
        }

        stage('Deploy Production') {
            when {
                branch 'main'
            }
            input {
                message 'Deploy to production?'
                ok 'Deploy'
                submitter 'admin,release-team'
            }
            steps {
                sh "kubectl set image deployment/app app=${IMAGE_NAME} -n production"
                sh "kubectl rollout status deployment/app -n production --timeout=300s"
            }
        }
    }

    post {
        success {
            slackSend(channel: '#deployments', message: "Build ${env.BUILD_NUMBER} succeeded")
        }
        failure {
            slackSend(channel: '#deployments', color: 'danger',
                      message: "Build ${env.BUILD_NUMBER} failed: ${env.BUILD_URL}")
        }
        always {
            cleanWs()
        }
    }
}

CloudWatch Custom Metrics and Alarms (AWS CDK) import * as cdk from 'aws-cdk-lib';
import * as cloudwatch from 'aws-cdk-lib/aws-cloudwatch';
import * as sns from 'aws-cdk-lib/aws-sns';
import * as actions from 'aws-cdk-lib/aws-cloudwatch-actions';

// Publish custom application metric
const orderProcessingLatency = new cloudwatch.Metric({
  namespace: 'MyApp/OrderService',
  metricName: 'ProcessingLatencyMs',
  dimensionsMap: { Environment: 'production', Service: 'order-service' },
  statistic: 'p99',
  period: cdk.Duration.minutes(5),
});

// Create alarm with composite evaluation
const latencyAlarm = new cloudwatch.Alarm(this, 'HighLatencyAlarm', {
  metric: orderProcessingLatency,
  threshold: 2000, // 2 seconds p99
  evaluationPeriods: 3,
  datapointsToAlarm: 2, // 2 of 3 periods must breach
  comparisonOperator: cloudwatch.ComparisonOperator.GREATER_THAN_THRESHOLD,
  treatMissingData: cloudwatch.TreatMissingData.NOT_BREACHING,
  alarmDescription: 'Order processing p99 latency exceeds 2s for 2 of 3 periods',
});

// Alarm action: notify on-call team
const oncallTopic = new sns.Topic(this, 'OncallTopic');
latencyAlarm.addAlarmAction(new actions.SnsAction(oncallTopic));

// CloudWatch Embedded Metric Format (application code)
const emfLog = {
  _aws: {
    Timestamp: Date.now(),
    CloudWatchMetrics: [{
      Namespace: 'MyApp/OrderService',
      Dimensions: [['Environment', 'Service']],
      Metrics: [{ Name: 'ProcessingLatencyMs', Unit: 'Milliseconds' }],
    }],
  },
  Environment: 'production',
  Service: 'order-service',
  ProcessingLatencyMs: 145,
  OrderId: 'ord-12345',
};
console.log(JSON.stringify(emfLog)); // CloudWatch agent extracts metric

Qualys API Integration for Vulnerability Reporting import requests
from datetime import datetime, timedelta

class QualysClient:
    def __init__(self, base_url: str, username: str, password: str):
        self.base_url = base_url
        self.session = requests.Session()
        self.session.auth = (username, password)
        self.session.headers.update({'X-Requested-With': 'Python'})

    def get_critical_vulnerabilities(self, days_back: int = 7) -> list:
        """Fetch critical/high vulnerabilities detected in the last N days."""
        since_date = (datetime.now() - timedelta(days=days_back)).strftime('%Y-%m-%d')

        params = {
            'action': 'list',
            'detection_updated_since': since_date,
            'severities': '4,5',  # 4=High, 5=Critical
            'status': 'New,Active,Re-Opened',
        }

        response = self.session.get(
            f'{self.base_url}/api/2.0/fo/asset/host/vm/detection/',
            params=params
        )
        response.raise_for_status()
        return self._parse_detections(response.text)

    def generate_patch_report(self, asset_group: str) -> dict:
        """Generate remediation report for an asset group."""
        params = {
            'action': 'list',
            'asset_group_titles': asset_group,
            'include_remediation': 1,
        }

        response = self.session.get(
            f'{self.base_url}/api/2.0/fo/report/',
            params=params
        )
        response.raise_for_status()
        return {
            'total_vulns': response.json().get('total', 0),
            'critical': response.json().get('severity_5', 0),
            'high': response.json().get('severity_4', 0),
            'remediation_steps': response.json().get('patches', []),
        }

BFS Template for Graph/Tree Problems public List<Integer> bfs(TreeNode root) {
    List<Integer> result = new ArrayList<>();
    if (root == null) return result;

    Queue<TreeNode> queue = new LinkedList<>();
    queue.offer(root);

    while (!queue.isEmpty()) {
        int levelSize = queue.size();
        for (int i = 0; i < levelSize; i++) {
            TreeNode node = queue.poll();
            result.add(node.val);
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }
    }
    return result;
}

Two Pointer Pattern public int[] twoSum(int[] sorted, int target) {
    int left = 0, right = sorted.length - 1;
    while (left < right) {
        int sum = sorted[left] + sorted[right];
        if (sum == target) return new int[]{left, right};
        else if (sum < target) left++;
        else right--;
    }
    return new int[]{-1, -1};
}

Sliding Window Pattern public int maxSumSubarray(int[] nums, int k) {
    int windowSum = 0, maxSum = Integer.MIN_VALUE;
    for (int i = 0; i < nums.length; i++) {
        windowSum += nums[i];
        if (i >= k - 1) {
            maxSum = Math.max(maxSum, windowSum);
            windowSum -= nums[i - (k - 1)];
        }
    }
    return maxSum;
}

Binary Search Implementation public int binarySearch(int[] arr, int target) {
    int low = 0, high = arr.length - 1;

    while (low <= high) {
        int mid = low + (high - low) / 2;  // Avoid integer overflow
        if (arr[mid] == target) return mid;
        else if (arr[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1;  // Not found
}

Dijkstra's Algorithm public int[] dijkstra(Map<Integer, List<int[]>> graph, int source, int n) {
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[source] = 0;

    // Priority queue: [distance, node]
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
    pq.offer(new int[]{0, source});

    while (!pq.isEmpty()) {
        int[] curr = pq.poll();
        int d = curr[0], u = curr[1];

        if (d > dist[u]) continue;  // Skip outdated entries

        for (int[] edge : graph.getOrDefault(u, List.of())) {
            int v = edge[0], weight = edge[1];
            if (dist[u] + weight < dist[v]) {
                dist[v] = dist[u] + weight;
                pq.offer(new int[]{dist[v], v});
            }
        }
    }
    return dist;
}

Dynamic Programming — Longest Common Subsequence public int longestCommonSubsequence(String text1, String text2) {
    int m = text1.length(), n = text2.length();
    int[][] dp = new int[m + 1][n + 1];

    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (text1.charAt(i - 1) == text2.charAt(j - 1)) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    return dp[m][n];
}

Behavioral Patterns Behavioral patterns are concerned with algorithms and the assignment of responsibilities between objects. The Strategy pattern defines a family of algorithms, encapsulates each one, and makes them interchangeable. The Observer pattern defines a one-to-many dependency between objects so that when one object changes state, all its dependents are notified automatically. Spring's event system (ApplicationEventPublisher and @EventListener) is a direct implementation of Observer. The Template Method pattern defines the skeleton of an algorithm in a superclass, letting subclasses override specific steps without changing the algorithm's structure. Spring's JdbcTemplate, RestTemplate, and TransactionTemplate all follow this pattern. The Command pattern encapsulates a request as an object, letting you parameterize clients with different requests, queue or log requests, and support undoable operations. Chain of Responsibility passes a request along a chain of handlers, where each handler decides either to process the request or pass it to the next handler. Spring Security's filter chain is a production example of this pattern. The State pattern allows an object to alter its behavior when its internal state changes, appearing to change its class. // Strategy Pattern with Spring dependency injection
public interface PaymentStrategy {
    PaymentResult process(PaymentRequest request);
}

@Component("creditCard")
public class CreditCardPayment implements PaymentStrategy {
    @Override
    public PaymentResult process(PaymentRequest request) {
        // Credit card processing logic
        return new PaymentResult(Status.SUCCESS, "CC-" + UUID.randomUUID());
    }
}

@Component("bankTransfer")
public class BankTransferPayment implements PaymentStrategy {
    @Override
    public PaymentResult process(PaymentRequest request) {
        // Bank transfer processing logic
        return new PaymentResult(Status.PENDING, "BT-" + UUID.randomUUID());
    }
}

@Service
public class PaymentService {
    private final Map<String, PaymentStrategy> strategies;

    // Spring injects all PaymentStrategy beans into this map keyed by bean name
    public PaymentService(Map<String, PaymentStrategy> strategies) {
        this.strategies = strategies;
    }

    public PaymentResult processPayment(String method, PaymentRequest request) {
        PaymentStrategy strategy = strategies.get(method);
        if (strategy == null) {
            throw new UnsupportedPaymentMethodException(method);
        }
        return strategy.process(request);
    }
} // Builder Pattern for complex object construction
@Builder
@Getter
public class OrderRequest {
    private final String customerId;
    private final List<OrderItem> items;
    private final ShippingAddress shippingAddress;
    private final PaymentMethod paymentMethod;
    @Builder.Default
    private final OrderPriority priority = OrderPriority.STANDARD;
    @Builder.Default
    private final boolean giftWrapping = false;
    private final String specialInstructions;

    // Lombok @Builder generates the builder class, but here is the manual equivalent:
    public static class OrderRequestBuilder {
        public OrderRequestBuilder addItem(String productId, int quantity, BigDecimal price) {
            if (this.items == null) this.items = new ArrayList<>();
            this.items.add(new OrderItem(productId, quantity, price));
            return this;
        }
    }
}

